selector_to_html = {"a[href=\"pycmplot_python_api.html#Highlighting-significant-loci-and-enable-gene-annotation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Highlighting significant loci and enable gene annotation<a class=\"headerlink\" href=\"#Highlighting-significant-loci-and-enable-gene-annotation\" title=\"Link to this heading\">\uf0c1</a></h2><p>Let\u2019s include <code class=\"docutils literal notranslate\"><span class=\"pre\">highlight</span></code> in the load step and rerun with highlighting. Note the extra column in the loaded sumstats.</p><p>We enable gene annotation by adding build information to the prep step. Remember the same order as sumstats and labels.</p>", "a[href=\"pycmplot_python_api.html##-Final-Notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"># Final Notes<a class=\"headerlink\" href=\"##-Final-Notes\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Specify-groups-of-sumstats-to-load-and-plot-in-different-panels\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Specify groups of sumstats to load and plot in different panels<a class=\"headerlink\" href=\"#Specify-groups-of-sumstats-to-load-and-plot-in-different-panels\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Python API for the pycmplot package<a class=\"headerlink\" href=\"#Python-API-for-the-pycmplot-package\" title=\"Link to this heading\">\uf0c1</a></h1><p>This tutorial is an end-to-end walkthrough of every user-facing feature in pycmplot from the Python API, working from the same synthetic dataset throughout so that every command is directly copy-pasteable. It\u2019s longer and more granular than <a class=\"reference external\" href=\"https://pycmplot.readthedocs.io/en/latest/quickstart.html#quickstart\">Quickstart</a> \u2014 read the quickstart first if you just want to see the shape of the API.</p>", "a[href=\"pycmplot_python_api.html#Selection-Statistics-from-our-2021-Scientific-Reports-Population-Structure-Paper\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Selection Statistics from our 2021 <em>Scientific Reports</em> <a class=\"reference external\" href=\"https://www.nature.com/articles/s41598-020-79124-1\">Population Structure Paper</a><a class=\"headerlink\" href=\"#Selection-Statistics-from-our-2021-Scientific-Reports-Population-Structure-Paper\" title=\"Link to this heading\">\uf0c1</a></h1><h2># Final Notes<a class=\"headerlink\" href=\"##-Final-Notes\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Important-Note\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Important Note<a class=\"headerlink\" href=\"#Important-Note\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Generating-a-linear-plot\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Generating a linear plot<a class=\"headerlink\" href=\"#Generating-a-linear-plot\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Highlighting-and-annotating-by-a-different-p-value-threshold\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Highlighting and annotating by a different p-value threshold<a class=\"headerlink\" href=\"#Highlighting-and-annotating-by-a-different-p-value-threshold\" title=\"Link to this heading\">\uf0c1</a></h2><p>The default highlight threshold is 5e-8. If we wish to highlight loci at another threshold, we need to add two more parameters</p>", "a[href=\"pycmplot_python_api.html###-Supplying-builds-with-summary-stats\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">## Supplying builds with summary stats<a class=\"headerlink\" href=\"###-Supplying-builds-with-summary-stats\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html###-QQ-Plotting\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">## QQ-Plotting<a class=\"headerlink\" href=\"###-QQ-Plotting\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Overlaying multiple<a class=\"headerlink\" href=\"#Overlaying-multiple\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"pycmplot_python_api.html#Ensuring-all-highlighted-loci-are-also-annotated\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Ensuring all highlighted loci are also annotated<a class=\"headerlink\" href=\"#Ensuring-all-highlighted-loci-are-also-annotated\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Explicitly speficying directory where output files should be stored<a class=\"headerlink\" href=\"#Explicitly-speficying-directory-where-output-files-should-be-stored\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"pycmplot_python_api.html#Plot-in-panels\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Plot in panels<a class=\"headerlink\" href=\"#Plot-in-panels\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Highlighting different categoris<a class=\"headerlink\" href=\"#Highlighting-different-categoris\" title=\"Link to this heading\">\uf0c1</a></h2><p>We will edit the hits overlay table generated above when cache was enabled.</p>", "a[href=\"pycmplot_python_api.html##-Handling-other-use-cases-and-QQ-plots\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"># Handling other use cases and QQ-plots<a class=\"headerlink\" href=\"##-Handling-other-use-cases-and-QQ-plots\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Installation\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#Installation\" title=\"Link to this heading\">\uf0c1</a></h1><p>Follow instructions in <a class=\"reference external\" href=\"https://pypi.org/project/pycmplot/\">https://pypi.org/project/pycmplot/</a></p>", "a[href=\"pycmplot_python_api.html#Getting-help\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Getting help<a class=\"headerlink\" href=\"#Getting-help\" title=\"Link to this heading\">\uf0c1</a></h2><p>To see the options of a function, simply run <code class=\"docutils literal notranslate\"><span class=\"pre\">help(function_name)</span></code></p><p>Example:</p>", "a[href=\"#python-api-tutorial\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Python API Tutorial<a class=\"headerlink\" href=\"#python-api-tutorial\" title=\"Link to this heading\">\uf0c1</a></h1><p>The interactive tutorial below demonstrates the full Python API using real\nsummary statistics data. It covers data loading, single- and multi-track\nlinear Manhattan plots, circular Manhattan plots, liftover, and the hits\nsummary table.</p>", "a[href=\"pycmplot_python_api.html#What-happens-if-we-try-highlighting-significant-loci-and-annotating-by-SNP?\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">What happens if we try highlighting significant loci and annotating by SNP?<a class=\"headerlink\" href=\"#What-happens-if-we-try-highlighting-significant-loci-and-annotating-by-SNP?\" title=\"Link to this heading\">\uf0c1</a></h2><p>It errors out because we did not include <code class=\"docutils literal notranslate\"><span class=\"pre\">highlight</span></code> in the data load step.</p>", "a[href=\"pycmplot_python_api.html#Annotating-by-specific-columns-in-hits-table\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Annotating by specific columns in hits table<a class=\"headerlink\" href=\"#Annotating-by-specific-columns-in-hits-table\" title=\"Link to this heading\">\uf0c1</a></h1><p>By <code class=\"docutils literal notranslate\"><span class=\"pre\">top_gene</span></code></p>", "a[href=\"pycmplot_python_api.html#Package-import-and-the-3-step-mental-model\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Package import and the 3-step mental model<a class=\"headerlink\" href=\"#Package-import-and-the-3-step-mental-model\" title=\"Link to this heading\">\uf0c1</a></h1><p>The Python API exposes the same pipeline as the CLI, with three explicit steps:</p>", "a[href=\"pycmplot_python_api.html#Controling-circular-plot-radius\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Controling circular plot radius<a class=\"headerlink\" href=\"#Controling-circular-plot-radius\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Ensuring all highlighted loci are also annotated<a class=\"headerlink\" href=\"#Ensuring-all-highlighted-loci-are-also-annotated\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Explicitly speficying directory where output files should be stored<a class=\"headerlink\" href=\"#Explicitly-speficying-directory-where-output-files-should-be-stored\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"pycmplot_python_api.html#Summary-stats-without-BUILD-column-and-no-build-information-provided\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Summary stats without <strong>BUILD</strong> column and no <code class=\"docutils literal notranslate\"><span class=\"pre\">build</span></code> information provided<a class=\"headerlink\" href=\"#Summary-stats-without-BUILD-column-and-no-build-information-provided\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>Notice that there are only two significant variants in the table.</strong></p>", "a[href=\"pycmplot_python_api.html#Generating-a-Circular-plot\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Generating a Circular plot<a class=\"headerlink\" href=\"#Generating-a-Circular-plot\" title=\"Link to this heading\">\uf0c1</a></h2><h3>No highlighting of significant loci<a class=\"headerlink\" href=\"#No-highlighting-of-significant-loci\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"pycmplot_python_api.html#Use-Cases---Real-Data\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use Cases - Real Data<a class=\"headerlink\" href=\"#Use-Cases---Real-Data\" title=\"Link to this heading\">\uf0c1</a></h1><p>Summary statistics for fetal hemoglobin (HbF) GWAS from different imputation panels from our 2025 <em>Nature Communications</em> <a class=\"reference external\" href=\"https://www.nature.com/articles/s41467-025-57413-5\">paper</a>.</p>", "a[href=\"pycmplot_python_api.html#Highlighting-different-categoris\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Highlighting different categoris<a class=\"headerlink\" href=\"#Highlighting-different-categoris\" title=\"Link to this heading\">\uf0c1</a></h2><p>We will edit the hits overlay table generated above when cache was enabled.</p>", "a[href=\"pycmplot_python_api.html#Multi-panel-Circular-Manhattan-Plotting\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-panel Circular Manhattan Plotting<a class=\"headerlink\" href=\"#Multi-panel-Circular-Manhattan-Plotting\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Specify groups of sumstats to load and plot in different panels<a class=\"headerlink\" href=\"#Specify-groups-of-sumstats-to-load-and-plot-in-different-panels\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Synthetic-Data\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Synthetic Data<a class=\"headerlink\" href=\"#Synthetic-Data\" title=\"Link to this heading\">\uf0c1</a></h1><p>See <a class=\"reference external\" href=\"https://pycmplot.readthedocs.io/en/latest/cli_tutorial.html#setup-a-synthetic-dataset\">docs</a> for details on generation of synthetic data.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tippy');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: true, theme: 'light-border',

            });
        };
    };
    console.log("tippy tips loaded!");
};
